  "reference_cpp": "#include <Arduino.h>\n#include <TM1637Display.h>\n#include <string.h>\n#include <stdlib.h>\n#include <ctype.h>\n\nTM1637Display display(8, 5);\nconst uint8_t buttonPins[4] = {2, 3, 4, 7};\nconst int prices[3] = {1, 2, 3};\nint stock[3] = {2, 2, 2};\nstruct Button {\n  bool rawPressed;\n  bool stablePressed;\n  unsigned long changedAt;\n};\nButton buttons[4];\nint selected = -1;\nbool adminMode = false;\nbool displayError = false;\nbool holdHandled = false;\nunsigned long confirmPressedAt = 0;\nunsigned long selectionAt = 0;\nint lastDisplayed = -32768;\nchar serialLine[48];\nuint8_t serialLength = 0;\nbool serialOverflow = false;\nunsigned long lastSerialByte = 0;\n\nvoid refreshDisplay(unsigned long now) {\n  int value;\n  if (displayError) value = -1;\n  else if (selected < 0) return;\n  else if (((now - selectionAt) / 1000UL) % 2UL == 0) value = selected + 1;\n  else value = prices[selected];\n  if (value != lastDisplayed) {\n    display.showNumberDec(value, false);\n    lastDisplayed = value;\n  }\n}\n\nvoid confirmSale() {\n  if (adminMode || selected < 0) return;\n  if (stock[selected] > 0) {\n    --stock[selected];\n    displayError = false;\n    Serial.print(\"dispense:item\");\n    Serial.println(selected + 1);\n    tone(6, 2000, 100);\n  } else {\n    displayError = true;\n    tone(6, 400, 300);\n  }\n}\n\nvoid processLine() {\n  serialLine[serialLength] = '\\0';\n  if (!serialOverflow && adminMode) {\n    char *p = serialLine;\n    while (*p && isspace((unsigned char)*p)) ++p;\n    char *command = p;\n    while (*p && !isspace((unsigned char)*p)) ++p;\n    if (*p) {\n      *p++ = '\\0';\n      while (*p && isspace((unsigned char)*p)) ++p;\n      char *number = p;\n      bool digits = false;\n      while (isdigit((unsigned char)*p)) { digits = true; ++p; }\n      char *numberEnd = p;\n      while (*p && isspace((unsigned char)*p)) ++p;\n      if (digits && *p == '\\0' && (numberEnd - number) <= 4) {\n        long amount = strtol(number, 0, 10);\n        int index = -1;\n        if (strcmp(command, \"RESTOCK1\") == 0) index = 0;\n        else if (strcmp(command, \"RESTOCK2\") == 0) index = 1;\n        else if (strcmp(command, \"RESTOCK3\") == 0) index = 2;\n        if (index >= 0 && amount >= 0 && amount <= 9999) {\n          long sum = (long)stock[index] + amount;\n          stock[index] = (int)(sum > 9999 ? 9999 : sum);\n        }\n      }\n    }\n  }\n  serialLength = 0;\n  serialOverflow = false;\n}\n\nvoid pollSerial(unsigned long now) {\n  while (Serial.available() > 0) {\n    char c = (char)Serial.read();\n    lastSerialByte = now;\n    if (c == '\\n' || c == '\\r') {\n      if (serialLength || serialOverflow) processLine();\n    } else if (!serialOverflow) {\n      if (serialLength < sizeof(serialLine) - 1) serialLine[serialLength++] = c;\n      else serialOverflow = true;\n    }\n  }\n  if ((serialLength || serialOverflow) && now - lastSerialByte >= 20UL) processLine();\n}\n\nvoid pollButtons(unsigned long now) {\n  for (uint8_t i = 0; i < 4; ++i) {\n    bool pressed = digitalRead(buttonPins[i]) == LOW;\n    Button &b = buttons[i];\n    if (pressed != b.rawPressed) {\n      b.rawPressed = pressed;\n      b.changedAt = now;\n    }\n    if (b.stablePressed != b.rawPressed && now - b.changedAt >= 30UL) {\n      b.stablePressed = b.rawPressed;\n      if (i < 3 && b.stablePressed) {\n        selected = i;\n        displayError = false;\n        selectionAt = now;\n        lastDisplayed = -32768;\n      } else if (i == 3) {\n        if (b.stablePressed) {\n          confirmPressedAt = b.changedAt;\n          holdHandled = false;\n        } else {\n          unsigned long held = b.changedAt - confirmPressedAt;\n          if (!holdHandled && held >= 2000UL) {\n            adminMode = !adminMode;\n            holdHandled = true;\n          }\n          if (!holdHandled) confirmSale();\n        }\n      }\n    }\n  }\n  if (buttons[3].stablePressed && buttons[3].rawPressed && !holdHandled && now - confirmPressedAt >= 2000UL) {\n    adminMode = !adminMode;\n    holdHandled = true;\n  }\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(6, OUTPUT);\n  pinMode(13, OUTPUT);\n  digitalWrite(6, LOW);\n  digitalWrite(13, LOW);\n  for (uint8_t i = 0; i < 4; ++i) {\n    pinMode(buttonPins[i], INPUT_PULLUP);\n    buttons[i].rawPressed = false;\n    buttons[i].stablePressed = false;\n    buttons[i].changedAt = millis();\n  }\n  display.setBrightness(7);\n  display.clear();\n}\n\nvoid loop() {\n  unsigned long now = millis();\n  pollButtons(now);\n  pollSerial(now);\n  refreshDisplay(now);\n}\n"
}
